for r in records:
 for k in ['meaning','target_2029','verified_status','permissions','parameters_anchors','acceptance']:
  value=r[k]
  for old,new in phrases.items():value=value.replace(old,new)
  value=re.sub(r'([\u0590-\u05ff])([A-Za-z0-9])',r'\1 \2',value)
  value=re.sub(r'([A-Za-z0-9])([\u0590-\u05ff])',r'\1 \2',value)
  r[k]=value
